template.value:
__global__ void $NAME$($TYPE$* __restrict__ data, int n) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        $END$
    }
}

for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < $N$; i += blockDim.x * gridDim.x) {
    $END$
}

int threads = $THREADS$;
int blocks = ($N$ + threads - 1) / threads;
$KERNEL$<<<blocks, threads>>>($ARGS$);
CUDA_CHECK(cudaGetLastError());
$END$

cudaEvent_t start__, stop__;
CUDA_CHECK(cudaEventCreate(&start__));
CUDA_CHECK(cudaEventCreate(&stop__));
CUDA_CHECK(cudaEventRecord(start__));
$END$
CUDA_CHECK(cudaEventRecord(stop__));
CUDA_CHECK(cudaEventSynchronize(stop__));
float ms__ = 0.f;
CUDA_CHECK(cudaEventElapsedTime(&ms__, start__, stop__));
printf("elapsed: %.3f ms\n", ms__);

kernel void $NAME$(device $TYPE$* data [[buffer(0)]],
                   constant uint& n [[buffer(1)]],
                   uint gid [[thread_position_in_grid]]) {
    if (gid < n) {
        $END$
    }
}

__kernel void $NAME$(__global $TYPE$* data, const uint n) {
    size_t gid = get_global_id(0);
    if (gid < n) {
        $END$
    }
}
